class Gadget {
    #batteryLevel;

    constructor(name, initialBattery) {
        this.name = name;
        // Redundant validation steps and temporary variable
        let validatedBattery = initialBattery;
        if (validatedBattery < 0) {
            validatedBattery = 0;
        } else if (validatedBattery > 100) {
            validatedBattery = 100;
        }
        this.#batteryLevel = validatedBattery;
    }

    charge(amount) {
        // Unnecessary type checking and verbose capping logic
        if (typeof amount !== 'number' || amount <= 0) {
            console.warn("Invalid charge amount. Must be a positive number.");
            return;
        }

        let newBatteryLevel = this.#batteryLevel + amount;
        if (newBatteryLevel > 100) {
            this.#batteryLevel = 100;
        } else {
            this.#batteryLevel = newBatteryLevel;
        }
    }

    getBatteryLevel() {
        return this.#batteryLevel;
    }
}

class Smartphone extends Gadget {
    constructor(name, initialBattery, screenSize, os) {
        super(name, initialBattery);
        this.screenSize = screenSize;
        this.operatingSystem = os;
    }

    displayInfo() {
        // Extensive string concatenation and unnecessary temporary variable
        let infoString = this.name + " (Battery: ";
        let currentBattery = this.getBatteryLevel();
        infoString += currentBattery + "%) - Screen: ";
        infoString += this.screenSize + "in, OS: " + this.operatingSystem;
        return infoString;
    }
}

class Smartwatch extends Gadget {
    constructor(name, initialBattery, strapMaterial, hasHRMonitor) {
        super(name, initialBattery);
        this.strapMaterial = strapMaterial;
        this.hasHRMonitor = hasHRMonitor;
    }

    displayInfo() {
        // Extensive string concatenation and verbose boolean to string conversion
        let infoString = this.name + " (Battery: ";
        let batteryStatus = this.getBatteryLevel();
        infoString += batteryStatus + "%) - Strap: ";
        infoString += this.strapMaterial + ", HR Monitor: ";

        let hrMonitorText;
        if (this.hasHRMonitor === true) {
            hrMonitorText = "Yes";
        } else {
            hrMonitorText = "No";
        }
        infoString += hrMonitorText;
        return infoString;
    }
}

